// @ts-check
import pg from 'pg';
import { randomBytes, randomUUID } from 'node:crypto';
import { applyStage02Migrations } from '../../src/platform/database/migrate.js';
import { createPostgresPool } from '../../src/platform/database/pool.js';

/** Test resources are identified by fresh random names, never an existing database.
 * Credentials are read from configuration and never included in diagnostic output.
 */
export async function createPostgresFixture({ poolMax = 1, stage02Only = false, stage03Only = false, stage04Only = false, stage05Only = false, stage06Only = false } = {}) {
    const connectionString = process.env.TEST_DATABASE_ADMIN_URL ?? process.env.DATABASE_URL;
    if (!connectionString) throw new Error('TEST_DATABASE_ADMIN_URL or DATABASE_URL is required for real PostgreSQL qualification.');
    const adminUrl = new URL(connectionString);
    if (!['localhost', '127.0.0.1', '[::1]'].includes(adminUrl.hostname)) {
        throw new Error('Database qualification is restricted to a local PostgreSQL server.');
    }
    const suffix = randomUUID().replaceAll('-', '');
    const database = `asi_q_${suffix}`;
    const migrator = `asi_m_${suffix}`;
    const runtime = `asi_r_${suffix}`;
    const password = randomBytes(32).toString('hex');
    const admin = new pg.Client({ connectionString, connectionTimeoutMillis: 3000 });
    let owner;
    let db;
    let databaseCreated = false;
    let migratorCreated = false;
    let runtimeCreated = false;
    async function close() {
        const errors = [];
        for (const resource of [db, owner]) {
            try { if (resource) await ('close' in resource ? resource.close() : resource.end()); }
            catch (error) { errors.push(error); }
        }
        try {
            // Only names generated by this invocation may be removed, even after partial setup.
            if (databaseCreated) await admin.query(`DROP DATABASE "${database}" WITH (FORCE)`);
            if (runtimeCreated) await admin.query(`DROP ROLE "${runtime}"`);
            if (migratorCreated) await admin.query(`DROP ROLE "${migrator}"`);
        } catch (error) { errors.push(error); }
        finally { await admin.end(); }
        if (errors.length) throw new AggregateError(errors, 'PostgreSQL fixture cleanup failed.');
    }
    try {
        await admin.connect();
        await admin.query(`CREATE ROLE "${migrator}" NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS`);
        migratorCreated = true;
        // Identifier and password are generated internally; no request data is interpolated.
        await admin.query(`CREATE ROLE "${runtime}" LOGIN PASSWORD '${password}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS`);
        runtimeCreated = true;
        await admin.query(`CREATE DATABASE "${database}" OWNER "${migrator}" TEMPLATE template0`);
        databaseCreated = true;
        const ownerUrl = new URL(adminUrl);
        ownerUrl.pathname = '/' + database;
        owner = new pg.Client({ connectionString: ownerUrl.href, connectionTimeoutMillis: 3000 });
        await owner.connect();
        if (!stage02Only) await owner.query('CREATE EXTENSION IF NOT EXISTS vector');
        await owner.query(`SET ROLE "${migrator}"`);
        const migrationResult = await applyStage02Migrations(owner, { stage02Only, stage03Only, stage04Only, stage05Only, stage06Only });
        await owner.query('RESET ROLE');
        const schemas = ['identity', 'product', 'planning', 'control', 'inference', 'knowledge', 'verification', 'automation', 'ops'];
        for (const schema of schemas) {
            await owner.query(`GRANT USAGE ON SCHEMA "${schema}" TO "${runtime}"`);
            await owner.query(`GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA "${schema}" TO "${runtime}"`);
            await owner.query(`GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA "${schema}" TO "${runtime}"`);
        }
        await owner.query(`REVOKE INSERT, UPDATE, DELETE ON ops.schema_migrations FROM "${runtime}"`);
        const runtimeUrl = new URL(ownerUrl);
        runtimeUrl.username = runtime;
        runtimeUrl.password = password;
        const poolConfig = { DATABASE_URL: runtimeUrl.href, DATABASE_POOL_MAX: poolMax, DATABASE_TIMEOUT_MS: 3000 };
        db = createPostgresPool(poolConfig, { stage02Only, stage03Only, stage04Only, stage05Only, stage06Only });
        return { admin, owner, db, database, migrator, runtime, ownerUrl, runtimeUrl, migrationResult, poolConfig, close };
    } catch (error) {
        await close();
        throw error;
    }
}
